'use strict';
// Procedural match audio: user-enabled only, with a master gain and no remote media.
const matchAudio={ctx:null,on:false,volume:.3,master:null,bed:null,crowd:null,voices:[],
async toggle(){try{if(!this.ctx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC){toast('Audio is not supported by this browser.');return}this.ctx=new AC();this.master=this.ctx.createGain();this.master.gain.value=0;this.master.connect(this.ctx.destination);this.crowd=this.ctx.createGain();this.crowd.gain.value=.18;this.crowd.connect(this.master);let buffer=this.ctx.createBuffer(1,this.ctx.sampleRate*3,this.ctx.sampleRate),data=buffer.getChannelData(0),smooth=0;for(let i=0;i<data.length;i++){smooth=.97*smooth+.03*(Math.random()*2-1);data[i]=smooth*2.8}this.bed=this.ctx.createBufferSource();this.bed.buffer=buffer;this.bed.loop=true;let filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1300;this.bed.connect(filter);filter.connect(this.crowd);this.bed.start()}await this.ctx.resume();this.on=!this.on;this.sync();render()}catch{toast('Sound could not start. You can continue with sound off.')}},
setVolume(v){this.volume=Number(v);this.sync()},
sync(){if(!this.ctx)return;this.master.gain.setTargetAtTime(this.on&&view==='Matchday'&&!document.hidden?this.volume:0,this.ctx.currentTime,.15)},
tone(freq,length,volume=.08,type='sine',delay=0){if(!this.ctx||!this.on)return;let t=this.ctx.currentTime+delay,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(volume,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+length);o.connect(g);g.connect(this.master);o.start(t);o.stop(t+length+.05);o.onended=()=>{o.disconnect();g.disconnect()}},
whistle(){this.tone(2350,.18,.06);this.tone(2650,.25,.045,'sine',.15)},
cheer(big=false){if(!this.ctx||!this.on)return;let t=this.ctx.currentTime;this.crowd.gain.cancelScheduledValues(t);this.crowd.gain.setTargetAtTime(big?.85:.45,t,.2);this.crowd.gain.setTargetAtTime(.18,t+2.8,.8);for(let i=0;i<(big?8:3);i++)this.tone(240+i*43,.7,.012,'triangle',i*.12)},
play(last,duration){if(!this.on)return;this.tone(180,.14,.055,'triangle');if(last.penalty){this.whistle();return}const timer=setTimeout(()=>{if(!this.on||view!=='Matchday')return;this.tone(75,.16,.09,'triangle');this.whistle();if(/TOUCHDOWN|INTERCEPTED|First down/.test(last.text))this.cheer(/TOUCHDOWN/.test(last.text))},duration*.82);this.voices.push(timer);if(this.voices.length>10)this.voices.shift()}};
window.matchAudio=matchAudio;
document.addEventListener('visibilitychange',()=>matchAudio.sync());
const resolveBeforeOfficials=resolveSnap;
function enforcePenalty(m,type){let k=m.poss,start=m.spot,defensive=['Offside','Defensive pass interference','Roughing the passer'].includes(type),distance=type==='Offensive holding'?10:type==='Defensive pass interference'?ri(8,22):type==='Roughing the passer'?15:5;let newSpot=defensive?Math.min(99,start+distance):Math.max(1,start-Math.min(distance,Math.max(1,Math.floor(start/2))));let actual=Math.abs(newSpot-start),automatic=['Defensive pass interference','Roughing the passer'].includes(type);m.penalties??=[{count:0,yards:0},{count:0,yards:0}];let charged=defensive?1-k:k;m.penalties[charged].count++;m.penalties[charged].yards+=actual;m.spot=newSpot;if(automatic||(defensive&&actual>=m.toGo)){m.down=1;m.toGo=Math.min(10,100-newSpot)}else m.toGo=clampDistance(m.toGo+(defensive?-actual:actual),100-newSpot);let club=clubs[charged===0?m.a:m.b][0];let text=`FLAG — ${type}, ${club}. ${actual} yards${actual<distance?' (half-distance / goal-line limit)':''}. ${automatic?'Automatic first down.':m.down===1&&defensive?'First down.':'Replay the down.'}`;m.official={signal:'flag',text,type,team:club};m.last={text,start,spot:newSpot,poss:k,passing:false,call:'Penalty',penalty:true,animation:'flag'};addEvent(text,true);pauseAuto();return m.last}
function clampDistance(n,max){return Math.max(1,Math.min(n,max))}
resolveSnap=function(){let m=state.live;if(!m||m.finished||m.halftime)return;let chance=rand();if(chance<.065){let type=chance<.016?'False start':chance<.030?'Offside':chance<.047?'Offensive holding':chance<.059?'Defensive pass interference':'Roughing the passer';return enforcePenalty(m,type)}let result=resolveBeforeOfficials();if(!result)return result;m.official={signal:/TOUCHDOWN|field goal!/.test(result.text)?'touchdown':/incomplete/.test(result.text)?'incomplete':/First down/.test(result.text)?'first':'whistle',text:/TOUCHDOWN/.test(result.text)?'TOUCHDOWN — score confirmed.':/incomplete/.test(result.text)?'Incomplete pass. Clock stopped.':/First down/.test(result.text)?'First down. Move the chains.':'Play dead. Ball spotted.'};result.animation=/sacked/.test(result.text)?'tackle':result.passing?'throw':result.call==='Outside run'?'juke':result.spot-result.start>7?'dive':'run';return result};
const screenBeforeOfficials=matchScreen;
matchScreen=function(){let html=screenBeforeOfficials(),m=state.live;if(!m)return html;let p=m.penalties||[{count:0,yards:0},{count:0,yards:0}];let panel=`<div class="officials-panel ${m.official?.signal==='flag'?'flagged':''}"><div><span class="official-icon">⚑</span><b>${m.official?.signal==='flag'?'PENALTY ENFORCED':'OFFICIAL’S CALL'}</b><p>${esc(m.official?.text||'Crew ready. Play will begin on the snap.')}</p></div><span>${clubs[m.a][0]} ${p[0].count}–${p[0].yards} &nbsp; | &nbsp; ${clubs[m.b][0]} ${p[1].count}–${p[1].yards}<small>Penalties – yards</small></span></div>`;html=html.replace('<div class="two section-gap">',panel+'<div class="two section-gap">');return html.replace('No penalties or challenges.','Selected penalties auto-enforced; no challenges.')};
